//! Emits `generated/phase.rs`: the exchange phases of the `tgDP`
//! enumeration with their codes, file extensions and namespaces.

use std::fmt::Write as _;

use crate::schema::Schema;

pub fn codes(schema: &Schema) -> Vec<String> {
    schema
        .simple
        .get("tgDP")
        .map(|dp| dp.enumeration.clone())
        .unwrap_or_default()
}

pub fn variant(code: &str) -> String {
    format!("X{}", code.replace('.', "_"))
}

pub fn emit(codes: &[String], sources: &str) -> String {
    let mut out = String::new();
    let _ = writeln!(
        out,
        "// @generated by xtask gen from {sources}; do not edit."
    );
    let _ = writeln!(
        out,
        "//! Exchange phases (`tgDP`) with their codes and namespaces.\n"
    );
    let _ = writeln!(out, "use crate::version::Version;\n");
    let _ = writeln!(
        out,
        "#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]"
    );
    let _ = writeln!(out, "pub enum Phase {{");
    for code in codes {
        let _ = writeln!(out, "    {},", variant(code));
    }
    let _ = writeln!(out, "}}\n");
    let _ = writeln!(out, "impl Phase {{");
    let _ = writeln!(out, "    pub const ALL: [Phase; {}] = [", codes.len());
    for code in codes {
        let _ = writeln!(out, "        Phase::{},", variant(code));
    }
    let _ = writeln!(out, "    ];\n");
    let _ = writeln!(out, "    /// The `DP` text: `83`, `89B`, `50.1`.");
    let _ = writeln!(out, "    pub fn code(self) -> &'static str {{");
    let _ = writeln!(out, "        match self {{");
    for code in codes {
        let _ = writeln!(out, "            Phase::{} => \"{code}\",", variant(code));
    }
    let _ = writeln!(out, "        }}");
    let _ = writeln!(out, "    }}\n");
    let _ = writeln!(out, "    pub fn from_code(code: &str) -> Option<Phase> {{");
    let _ = writeln!(out, "        match code.trim() {{");
    for code in codes {
        let _ = writeln!(
            out,
            "            \"{code}\" => Some(Phase::{}),",
            variant(code)
        );
    }
    let _ = writeln!(out, "            _ => None,");
    let _ = writeln!(out, "        }}");
    let _ = writeln!(out, "    }}\n");
    let _ = writeln!(
        out,
        "    /// The phase a file extension such as `X83` or `x86zr` names."
    );
    let _ = writeln!(
        out,
        "    pub fn from_extension(extension: &str) -> Option<Phase> {{"
    );
    let _ = writeln!(
        out,
        "        let upper = extension.trim_start_matches('.').to_ascii_uppercase();"
    );
    let _ = writeln!(out, "        let code = upper.strip_prefix('X')?;");
    let _ = writeln!(out, "        Phase::from_code(code)");
    let _ = writeln!(out, "    }}\n");
    let _ = writeln!(out, "    /// The XML namespace of this phase in a version.");
    let _ = writeln!(
        out,
        "    pub fn namespace(self, version: Version) -> Option<String> {{"
    );
    let _ = writeln!(out, "        match version {{");
    let _ = writeln!(
        out,
        "            Version::V30 | Version::V31 => Some(\"http://www.gaeb.de/GAEB_DA_XML/200407\".to_string()),"
    );
    let _ = writeln!(out, "            Version::V32 | Version::V33 => {{");
    let _ = writeln!(
        out,
        "                Some(format!(\"http://www.gaeb.de/GAEB_DA_XML/DA{{}}/{{}}\", self.code(), version.as_str()))"
    );
    let _ = writeln!(out, "            }}");
    let _ = writeln!(out, "        }}");
    let _ = writeln!(out, "    }}");
    let _ = writeln!(out, "}}");
    out
}
